// ─────────────────────────────────────────────────────────────────────────
//  01 · generic helpers★★☆
//  concepts: bounded type parameters · ? extends · ? super
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** The largest element; NoSuchElementException when empty. */
    static <T extends Comparable<? super T>> T max(Collection<? extends T> items) {
        Iterator<? extends T> it = items.iterator();
        if (!it.hasNext()) throw new NoSuchElementException("empty collection");
        T best = it.next();
        while (it.hasNext()) {
            T x = it.next();
            if (x.compareTo(best) > 0) best = x;
        }
        return best;
    }

    /** Sum of the numbers as doubles. */
    static double sum(Collection<? extends Number> nums) {
        double total = 0;
        for (Number n : nums) total += n.doubleValue();
        return total;
    }

    /** Appends src to dest; returns how many elements were copied. */
    static <T> int copyInto(List<? super T> dest, Collection<? extends T> src) {
        int n = 0;
        for (T x : src) {
            dest.add(x);
            n++;
        }
        return n;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("max works for numbers and strings", () -> eq(List.of(max(List.of(3, 9, 2)), max(Set.of("kiwi", "apple", "pear"))), List.of(9, "pear")));
        test("max of an empty collection throws (boundary)", () -> raises(NoSuchElementException.class, () -> max(new ArrayList<Integer>())));
        test("sum accepts any Number list", () -> approx(sum(List.of(1, 2.5, 3L)), 6.5));
        test("an Integer list copies into a Number list", () -> {
            List<Number> dest = new ArrayList<>(List.of(0.5));
            int n = copyInto(dest, List.of(1, 2));
            eq(n, 2);
            eq(dest, List.of(0.5, 1, 2));
        });
        test("copying nothing changes nothing", () -> { List<Object> d = new ArrayList<>(); eq(copyInto(d, List.of()), 0); ok(d.isEmpty(), "dest stays empty"); });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

fund-java/06-generics-and-wildcards/01-p.explanation:
The signatures do most of the work; the bodies are short:

```java
static <T extends Comparable<? super T>> T max(Collection<? extends T> items) {
    Iterator<? extends T> it = items.iterator();
    if (!it.hasNext()) throw new NoSuchElementException("empty");
    T best = it.next();
    while (it.hasNext()) { T x = it.next(); if (x.compareTo(best) > 0) best = x; }
    return best;
}
```

`copyInto` reads Ts from a producer (`? extends T`) and writes them into a consumer (`? super T`), which is why an `Integer` list can be copied into a `Number` list.
